180	#[allow(clippy::too_many_arguments)]
181	fn call_run(
182	    agent: &Agent,
183	    config: &Config,
184	    request_level: bool,
185	    mut call: Call<Prepare>,
186	    body: &mut SendBody,
187	    redirect_count: u32,
188	    redirect_history: &mut Option<Vec<Uri>>,
189	    timings: &mut CallTimings,
190	) -> Result<CallResult, Error> {
191	    let uri = call.uri().clone();
192	    debug!("{} {:?}", call.method(), DebugUri(call.uri()));
193	
194	    if config.https_only() && uri.scheme() != Some(&Scheme::HTTPS) {
195	        return Err(Error::RequireHttpsOnly(uri.to_string()));
196	    }
197	
198	    add_headers(&mut call, agent, config, body, &uri)?;
199	
200	    let mut connection = connect(agent, config, request_level, &uri, timings)?;
201	
202	    let mut call = call.proceed();
203	
204	    if log_enabled!(log::Level::Debug) {
205	        let headers = call.headers_map()?;
206	
207	        let r = DebugRequest {
208	            method: call.method(),
209	            uri: call.uri(),
210	            version: call.version(),
211	            headers,
212	        };
213	        debug!("{:?}", r);
214	    }
215	
216	    let call = match send_request(call, &mut connection, timings)? {
217	        SendRequestResult::Await100(call) => match await_100(call, &mut connection, timings)? {
218	            Await100Result::SendBody(call) => send_body(call, body, &mut connection, timings)?,
219	            Await100Result::RecvResponse(call) => call,
220	        },
221	        SendRequestResult::SendBody(call) => send_body(call, body, &mut connection, timings)?,
222	        SendRequestResult::RecvResponse(call) => call,
223	    };
224	
225	    let is_following_redirects = redirect_count < config.max_redirects();
226	
227	    let (mut response, response_result) = recv_response(
228	        call,
229	        &mut connection,
230	        config,
231	        timings,
232	        is_following_redirects,
233	    )?;
234	
235	    debug!("{:?}", DebugResponse(&response));
236	
237	    #[cfg(feature = "cookies")]
238	    {
239	        let mut jar = agent.cookie_jar_lock();
240	
241	        let iter = response
242	            .headers()
243	            .get_all(http::header::SET_COOKIE)
244	            .iter()
245	            .filter_map(|h| h.to_str().ok())
246	            .filter_map(|s| crate::Cookie::parse(s, &uri).ok());
247	
248	        jar.store_response_cookies(iter, &uri);
249	    }
250	
251	    if let Some(history) = redirect_history.as_mut() {
252	        history.push(uri.clone());
253	        response
254	            .extensions_mut()
255	            .insert(RedirectHistory(history.clone()));
256	    }
257	    response.extensions_mut().insert(ResponseUri(uri));
258	
259	    let ret = match response_result {
260	        RecvResponseResult::RecvBody(call) => {
261	            let timings = mem::take(timings);
262	            let mut handler = BodyHandler {
263	                call: Some(call),
264	                connection: Some(connection),
265	                timings,
266	                ..Default::default()
267	            };
268	
269	            if response.status().is_redirection() {
270	                if is_following_redirects {
271	                    let location = response.headers().get(header::LOCATION).cloned();
272	                    let call = handler.consume_redirect_body()?;
273	
274	                    CallResult::Redirect(call, handler.timings, location)
275	                } else if config.max_redirects_do_error() {
276	                    return Err(Error::TooManyRedirects);
277	                } else {
278	                    CallResult::Response(response, handler)
279	                }
280	            } else {
281	                CallResult::Response(response, handler)
282	            }
283	        }
284	        RecvResponseResult::Redirect(call) => {
285	            cleanup(connection, call.must_close_connection(), timings.now());
286	
287	            if is_following_redirects {
288	                let location = response.headers().get(header::LOCATION).cloned();
289	                CallResult::Redirect(call, mem::take(timings), location)
290	            } else if config.max_redirects_do_error() {
291	                return Err(Error::TooManyRedirects);
292	            } else {
293	                CallResult::Response(response, BodyHandler::default())
294	            }
295	        }
296	        RecvResponseResult::Cleanup(call) => {
297	            cleanup(connection, call.must_close_connection(), timings.now());
298	            CallResult::Response(response, BodyHandler::default())
299	        }
300	    };
301	
302	    Ok(ret)
303	}
