408	fn connect(
409	    agent: &Agent,
410	    config: &Config,
411	    request_level: bool,
412	    uri: &Uri,
413	    timings: &mut CallTimings,
414	) -> Result<Connection, Error> {
415	    // Before resolving the URI we need to ensure it is a full URI. We
416	    // cannot make requests with partial uri like "/path".
417	    uri.ensure_valid_url()?;
418	
419	    let is_proxy = config.proxy().is_some();
420	
421	    // For most proxy configs, the proxy itself should resolve the host name we are connecting to.
422	    // However for SOCKS4, we must do it and pass the resolved IP to the proxy.
423	    let is_proxy_local_resolve = config.proxy().map(|p| p.resolve_target()).unwrap_or(false);
424	
425	    // Tells if this host matches NO_PROXY
426	    let is_no_proxy = config.proxy().map(|p| p.is_no_proxy(uri)).unwrap_or(false);
427	
428	    let addrs = if is_no_proxy || !is_proxy || is_proxy_local_resolve {
429	        agent
430	            .resolver
431	            .resolve(uri, config, timings.next_timeout(Timeout::Resolve))?
432	    } else {
433	        agent.resolver.empty()
434	    };
435	
436	    timings.record_time(Timeout::Resolve);
437	
438	    let details = ConnectionDetails {
439	        uri,
440	        addrs,
441	        resolver: &*agent.resolver,
442	        config,
443	        request_level,
444	        now: timings.now(),
445	        timeout: timings.next_timeout(Timeout::Connect),
446	        current_time: timings.current_time(),
447	        run_connector: agent.run_connector.clone(),
448	    };
449	
450	    let use_pool = config.can_share_pool_with(&agent.config);
451	    let max_idle_age = config.max_idle_age().into();
452	    let connection = agent.pool.connect(&details, max_idle_age, use_pool)?;
453	
454	    if details.needs_tls() && !connection.is_tls() {
455	        return Err(Error::TlsRequired);
456	    }
457	
458	    timings.record_time(Timeout::Connect);
459	
460	    Ok(connection)
461	}
