463	fn send_request(
464	    mut call: Call<SendRequest>,
465	    connection: &mut Connection,
466	    timings: &mut CallTimings,
467	) -> Result<SendRequestResult, Error> {
468	    loop {
469	        if call.can_proceed() {
470	            break;
471	        }
472	
473	        let buffers = connection.buffers();
474	        let amount = call.write(buffers.output())?;
475	        let timeout = timings.next_timeout(Timeout::SendRequest);
476	        connection.transmit_output(amount, timeout)?;
477	    }
478	
479	    timings.record_time(Timeout::SendRequest);
480	
481	    // The request might be misconfigured.
482	    let call = call.proceed()?;
483	
484	    // We checked can_proceed() above, this unwrap is fine.
485	    Ok(call.unwrap())
486	}
