488	fn await_100(
489	    mut call: Call<Await100>,
490	    connection: &mut Connection,
491	    timings: &mut CallTimings,
492	) -> Result<Await100Result, Error> {
493	    while call.can_keep_await_100() {
494	        let timeout = timings.next_timeout(Timeout::Await100);
495	
496	        if timeout.after.is_zero() {
497	            if timeout.reason == Timeout::Await100 {
498	                // Stop waiting for 100-continue.
499	                break;
500	            }
501	            return Err(Error::Timeout(timeout.reason));
502	        }
503	
504	        match connection.maybe_await_input(timeout) {
505	            Ok(_) => {
506	                let input = connection.buffers().input();
507	                if input.is_empty() {
508	                    return Err(Error::disconnected("await_100 empty input"));
509	                }
510	
511	                let amount = call.try_read_100(input)?;
512	                if amount > 0 {
513	                    connection.consume_input(amount);
514	                    break;
515	                }
516	            }
517	            Err(Error::Timeout(Timeout::Await100)) => {
518	                // If we get a timeout while waiting for input, that is not an error,
519	                // we progress to send the request body.
520	                break;
521	            }
522	            Err(e) => return Err(e),
523	        }
524	    }
525	
526	    timings.record_time(Timeout::Await100);
527	
528	    // A misconfigured request might surface here.
529	    let call = call.proceed()?;
530	
531	    Ok(call)
532	}
