644	fn handle_redirect(mut call: Call<Redirect>, config: &Config) -> Result<Call<Prepare>, Error> {
645	    let maybe_new_call = call.as_new_call(config.redirect_auth_headers())?;
646	    let status = call.status();
647	
648	    if let Some(call) = maybe_new_call {
649	        debug!(
650	            "Redirect ({}): {} {:?}",
651	            status,
652	            call.method(),
653	            DebugUri(call.uri())
654	        );
655	
656	        Ok(call)
657	    } else {
658	        Err(Error::RedirectFailed)
659	    }
660	}
661	
662	/// A snapshot of a request, used to rebuild it when a 307/308 redirect
663	/// requires the body to be replayed.
664	///
665	/// Extensions are not carried over. They are either consumed when setting
666	/// up the call (such as [`RequestLevelConfig`]) or not relevant for a
667	/// redirected request.
668	fn request_template(request: &Request<()>) -> Request<()> {
669	    let mut template = Request::new(());
670	    *template.method_mut() = request.method().clone();
671	    *template.uri_mut() = request.uri().clone();
672	    *template.version_mut() = request.version();
673	    *template.headers_mut() = request.headers().clone();
674	    template
675	}
676	
677	fn request_template_from_call(call: &Call<Prepare>) -> Request<()> {
678	    let mut template = Request::new(());
679	    *template.method_mut() = call.method().clone();
680	    *template.uri_mut() = call.uri().clone();
681	    *template.version_mut() = call.version();
682	    *template.headers_mut() = call.headers().clone();
683	    template
684	}
685	
686	/// Build the request for a 307/308 redirect that replays the request body.
687	///
688	/// The method and headers are retained from the previous request. This
689	/// mirrors the header handling in ureq-proto's redirect logic, except that
690	/// a caller-provided `Content-Length`/`Transfer-Encoding` is kept, since the
691	/// replayed body is byte-identical to what was first sent.
692	fn redirect_replay_request(
693	    template: &Request<()>,
694	    location: Option<&HeaderValue>,
695	    config: &Config,
696	) -> Result<Request<()>, Error> {
697	    let header = location.ok_or(ureq_proto::Error::NoLocationHeader)?;
698	
699	    let location = header.to_str().map_err(|_| {
700	        ureq_proto::Error::BadLocationHeader(String::from_utf8_lossy(header.as_bytes()).to_string())
701	    })?;
702	
703	    let uri = new_uri_from_location(template.uri(), location)?;
704	
705	    let keep_auth_header = match config.redirect_auth_headers() {
706	        RedirectAuthHeaders::SameHost => can_redirect_auth_header(template.uri(), &uri),
707	        _ => false,
708	    };
709	
710	    let mut request = request_template(template);
711	    *request.uri_mut() = uri;
712	
713	    // Mutate the request to remove headers we cannot keep in the redirect.
714	    let headers = request.headers_mut();
715	    if !keep_auth_header {
716	        headers.remove(header::AUTHORIZATION);
717	    }
718	    headers.remove(header::COOKIE);
719	
720	    Ok(request)
721	}
722	
723	fn can_redirect_auth_header(prev: &Uri, next: &Uri) -> bool {
724	    let host_prev = prev.authority().map(|a| a.host());
725	    let host_next = next.authority().map(|a| a.host());
726	    let scheme_prev = prev.scheme();
727	    let scheme_next = next.scheme();
728	    host_prev == host_next && (scheme_prev == scheme_next || scheme_next == Some(&Scheme::HTTPS))
729	}
730	
731	fn cleanup(connection: Connection, must_close: bool, now: Instant) {
732	    if must_close {
733	        connection.close();
734	    } else {
735	        connection.reuse(now)
736	    }
737	}
738	
739	#[derive(Default)]
740	pub(crate) struct BodyHandler {
741	    call: Option<Call<RecvBody>>,
742	    connection: Option<Connection>,
743	    timings: CallTimings,
744	    remote_closed: bool,
745	    redirect: Option<Box<Call<Redirect>>>,
746	}
747	
748	impl BodyHandler {
749	    fn do_read(&mut self, buf: &mut [u8]) -> Result<usize, Error> {
750	        let (Some(call), Some(connection), timings) =
751	            (&mut self.call, &mut self.connection, &mut self.timings)
752	        else {
753	            return Ok(0);
754	        };
755	
756	        loop {
757	            let body_fulfilled = match call.body_mode() {
758	                BodyMode::NoBody => unreachable!("must be a BodyMode for BodyHandler"),
759	                // These modes are fulfilled by either reaching the content-length or
760	                // receiving an end chunk delimiter.
761	                BodyMode::LengthDelimited(_) | BodyMode::Chunked => call.can_proceed(),
762	                // This mode can only end once remote closes
763	                BodyMode::CloseDelimited => false,
764	            };
765	
766	            if body_fulfilled {
767	                self.ended()?;
768	                return Ok(0);
769	            }
770	
771	            let has_buffered_input = connection.buffers().can_use_input();
772	
773	            // First try to use input already buffered
774	            if has_buffered_input {
775	                let input = connection.buffers().input();
776	                let (input_used, output_used) = call.read(input, buf)?;
777	                connection.consume_input(input_used);
778	
779	                if output_used > 0 {
780	                    return Ok(output_used);
781	                }
782	
783	                if input_used > 0 {
784	                    // Body might be fulfilled now.
785	                    continue;
786	                }
787	            }
788	
789	            if self.remote_closed {
790	                // we should not try to await_input again.
791	                self.ended()?;
792	                return Ok(0);
793	            }
794	
795	            let timeout = timings.next_timeout(Timeout::RecvBody);
796	
797	            let made_progress = match connection.maybe_await_input(timeout) {
798	                Ok(v) => v,
799	                Err(Error::Io(e)) => match e.kind() {
800	                    io::ErrorKind::UnexpectedEof
801	                    | io::ErrorKind::ConnectionAborted
802	                    | io::ErrorKind::ConnectionReset => {
803	                        self.remote_closed = true;
804	                        true
805	                    }
806	                    _ => return Err(Error::Io(e)),
807	                },
808	                Err(e) => return Err(e),
809	            };
810	
811	            let input = connection.buffers().input();
812	            let input_ended = input.is_empty();
813	
814	            let (input_used, output_used) = call.read(input, buf)?;
815	            connection.consume_input(input_used);
816	
817	            if output_used > 0 {
818	                return Ok(output_used);
819	            } else if input_ended {
820	                self.ended()?;
821	                return Ok(0);
822	            } else if made_progress {
823	                // The maybe_await_input() made progress, but handled amount is 0. This
824	                // can for instance happen if we read some data, but not enough for
825	                // decoding any gzip.
826	                continue;
827	            } else {
828	                // This is an error case we don't want to see.
829	                return Err(Error::BodyStalled);
830	            }
831	        }
832	    }
833	
834	    fn ended(&mut self) -> Result<(), Error> {
835	        self.timings.record_time(Timeout::RecvBody);
836	
837	        let call = self.call.take().expect("ended() called with body");
838	
839	        // In some cases, when reading chunked, the server send 0\r\n to indicate
840	        // the end of the body, and then abruptly does a FIN. In these cases we have
841	        // received the entire body, but must clean up the connection.
842	        let is_ended_chunked = call.is_ended_chunked();
843	
844	        let mut force_close = false;
845	
846	        if !call.can_proceed() {
847	            if is_ended_chunked {
848	                // This case means we got 0\r\n, but can_proceed() is false because
849	                // it only goes true on fully received chunked bodies.
850	                debug!("Server ended connection after sending chunked 0\\r\\n");
851	                force_close = true;
852	            } else {
853	                return Err(Error::disconnected("ended call cannot proceed"));
854	            }
855	        }
856	
857	        let must_close_connection = force_close
858	            || match call.proceed().unwrap() {
859	                RecvBodyResult::Redirect(call) => {
860	                    let c = call.must_close_connection();
861	                    self.redirect = Some(Box::new(call));
862	                    c
863	                }
864	                RecvBodyResult::Cleanup(v) => v.must_close_connection(),
865	            };
866	
867	        let connection = self.connection.take().expect("ended() called with body");
868	        cleanup(connection, must_close_connection, self.timings.now());
869	
870	        Ok(())
871	    }
872	
873	    fn consume_redirect_body(&mut self) -> Result<Call<Redirect>, Error> {
874	        let mut buf = vec![0; 1024];
875	        loop {
876	            let amount = self.do_read(&mut buf)?;
877	            if amount == 0 {
878	                break;
879	            }
880	        }
881	
882	        // Unwrap is OK, because we are only consuming the redirect body if
883	        // such a body was signalled by the remote.
884	        let redirect = self.redirect.take().map(|b| *b);
885	        Ok(redirect.expect("remote to have signaled redirect"))
886	    }
887	}
888	
889	impl io::Read for BodyHandler {
890	    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
891	        self.do_read(buf).map_err(|e| e.into_io())
892	    }
893	}
