115	    pub fn transmit_output(&mut self, amount: usize, timeout: NextTimeout) -> Result<(), Error> {
116	        // An already expired budget must fail here. Transports can't set a zero
117	        // socket timeout and would instead grant a short grace period per call.
118	        if timeout.after.is_zero() {
119	            return Err(Error::Timeout(timeout.reason));
120	        }
121	        self.transport.transmit_output(amount, timeout)
122	    }
123	
124	    pub fn maybe_await_input(&mut self, timeout: NextTimeout) -> Result<bool, Error> {
125	        if timeout.after.is_zero() {
126	            return Err(Error::Timeout(timeout.reason));
127	        }
128	        self.transport.maybe_await_input(timeout)
129	    }
