140	    pub fn reuse(mut self, now: Instant) {
141	        if !self.transport.buffers().input().is_empty() {
142	            // Unconsumed input means the server sent more bytes than the body
143	            // we read. Same condition as the probe below, only the bytes are
144	            // already in our buffer instead of still in the socket.
145	            debug!("Unconsumed input. Closing connection");
146	            return;
147	        }
148	
149	        if !self.transport.is_open() {
150	            // The purpose of probing is that is_open() for tcp connector attempts
151	            // to read some more bytes. If that succeeds, the connection is considered
152	            // _NOT_ open, since that means we either failed to read the previous
153	            // body to end, or the server sent bogus data after the body. Either
154	            // is a condition where we mustn't reuse the connection.
155	            return;
