159	        let Some(arc) = self.pool.upgrade() else {
160	            debug!("Pool gone: {:?}", self.key);
161	            return;
162	        };
163	
164	        debug!("Return to pool: {:?}", self.key);
165	
166	        let mut pool = arc.lock().unwrap();
167	
168	        pool.add(self);
169	        pool.purge(now);
170	    }
