217	struct Pool {
218	    lru: VecDeque<Connection>,
219	    max_idle_connections: usize,
220	    max_idle_connections_per_host: usize,
221	    max_idle_age: Duration,
222	}
223	
224	impl Pool {
225	    fn new(config: &Config) -> Self {
226	        Pool {
227	            lru: VecDeque::new(),
228	            max_idle_connections: config.max_idle_connections(),
229	            max_idle_connections_per_host: config.max_idle_connections_per_host(),
230	            max_idle_age: config.max_idle_age().into(),
231	        }
232	    }
233	
234	    fn purge(&mut self, now: Instant) {
235	        while self.lru.len() > self.max_idle_connections || self.front_is_too_old(now) {
236	            self.lru.pop_front();
237	        }
238	
239	        self.update_position_per_host();
240	
241	        let max = self.max_idle_connections_per_host;
242	
243	        // unwrap is ok because update_position_per_host() should have set all
244	        self.lru.retain(|c| c.position_per_host.unwrap() < max);
245	    }
246	
247	    fn front_is_too_old(&self, now: Instant) -> bool {
248	        self.lru.front().map(|c| c.age(now)) > Some(self.max_idle_age)
249	    }
250	
251	    fn update_position_per_host(&mut self) {
252	        // Reset position counters
253	        for c in &mut self.lru {
254	            c.position_per_host = None;
255	        }
256	
257	        loop {
258	            let maybe_uncounted = self
259	                .lru
260	                .iter()
261	                .rev()
262	                .find(|c| c.position_per_host.is_none());
263	
264	            let Some(uncounted) = maybe_uncounted else {
265	                break; // nothing more to count.
266	            };
267	
268	            let key_to_count = uncounted.key.clone();
269	
270	            for (position, c) in self
271	                .lru
272	                .iter_mut()
273	                .rev()
274	                .filter(|c| c.key == key_to_count)
275	                .enumerate()
276	            {
277	                c.position_per_host = Some(position);
278	            }
279	        }
280	    }
281	
282	    fn add(&mut self, conn: Connection) {
283	        self.lru.push_back(conn)
284	    }
285	
286	    fn get(&mut self, key: &PoolKey, max_idle_age: Duration, now: Instant) -> Option<Connection> {
287	        while let Some(i) = self.lru.iter().position(|c| c.key == *key) {
288	            let mut conn = self.lru.remove(i).unwrap(); // unwrap ok since we just got the position
289	
290	            // Before we release the connection, we probe that it appears to still work.
291	            if !conn.is_open() {
292	                // This connection is broken. Try find another one.
293	                continue;
294	            }
295	
296	            if conn.age(now) >= max_idle_age {
297	                // A max_duration that is shorter in the request than the pool.
298	                // This connection survives in the pool, but is not used for this
299	                // specific connection.
300	                continue;
301	            }
302	
303	            return Some(conn);
304	        }
305	        None
306	    }
307	}
