145	    pub(crate) fn record_time(&mut self, timeout: Timeout) {
146	        // Each time should only be recorded once
147	        assert!(
148	            self.time_of(timeout).is_none(),
149	            "{:?} recorded more than once",
150	            timeout
151	        );
152	
153	        // There need to be at least one preceeding time recorded
154	        // since it follows a graph/call tree.
155	        let any_preceeding = timeout
156	            .preceeding()
157	            .filter_map(|to_check| self.time_of(to_check))
158	            .any(|_| true);
159	
160	        assert!(any_preceeding, "{:?} has no preceeding", timeout);
161	
162	        // Record the time
163	        self.times.push((timeout, self.current_time.now()));
164	    }
