170	    pub(crate) fn next_timeout(&self, timeout: Timeout) -> NextTimeout {
171	        let now = self.now();
172	
173	        let (reason, at) = timeout
174	            .timeouts_to_check()
175	            .filter_map(|to_check| {
176	                let timeout = to_check.configured_timeout(&self.timeouts)?;
177	                // Global and PerCall record their starts. Other timestamps
178	                // record completion, which starts the next phase's budget.
179	                let time = match to_check {
180	                    Timeout::Global | Timeout::PerCall => self.time_of(to_check),
181	                    _ => to_check
182	                        .preceeding()
183	                        .filter_map(|previous| self.time_of(previous))
184	                        .max(),
185	                }
186	                .expect("timeout has no recorded start");
187	                Some((to_check, time + timeout))
188	            })
189	            .min_by(|a, b| a.1.cmp(&b.1))
190	            .unwrap_or((Timeout::Global, Instant::NotHappening));
