214	    pub fn run(&self, request: Request<impl AsSendBody>) -> Result<Response<Body>, Error> {
215	        let (parts, mut body) = request.into_parts();
216	        let mut body = body.as_body();
217	        let mut request = Request::from_parts(parts, ());
