/// Reset the per-phase records to resend the request on a new connection.
///
/// Unlike [`CallTimings::new_call`], this keeps the PerCall budget running
/// from its original start: a resend after a disconnect shares the global
/// and per-call budgets of the failed attempt, while each phase limit
/// (resolve, connect, send request, etc) applies afresh.
pub(crate) fn for_retry(mut self) -> CallTimings {
    self.times.truncate(2); // Global and PerCall are in positions 0 and 1.

    CallTimings {
        timeouts: self.timeouts,
        per_read: self.per_read,
        per_write: self.per_write,
        current_time: self.current_time,
        times: self.times,
    }
}

