fn handle_conn(stream: TcpStream, on_reuse: OnReuse, requests: Arc<Mutex<Vec<Recorded>>>) {
    stream.set_read_timeout(Some(Duration::from_secs(10))).unwrap();
    let mut writer = stream.try_clone().unwrap();
    let mut reader = BufReader::new(stream);
    let mut n = 0;
    loop {
        n += 1;
        // Request line
        let mut line = String::new();
        if reader.read_line(&mut line).unwrap_or(0) == 0 {
            return; // client went away
        }
        let mut parts = line.trim().split_whitespace();
        let method = parts.next().unwrap_or("").to_string();
        let target = parts.next().unwrap_or("").to_string();

        let mut content_length = 0usize;
        let mut expect_100 = false;
        loop {
            let mut h = String::new();
            if reader.read_line(&mut h).unwrap_or(0) == 0 { return; }
            let h = h.trim();
            if h.is_empty() { break; }
            if let Some((name, value)) = h.split_once(':') {
                if name.eq_ignore_ascii_case("content-length") {
                    content_length = value.trim().parse().unwrap_or(0);
                }
                if name.eq_ignore_ascii_case("expect") && value.trim().eq_ignore_ascii_case("100-continue") {
                    expect_100 = true;
                }
            }
        }

        if n > 1 {
            // This connection was reused. Act per mode.
            match on_reuse {
                OnReuse::Close => {}
                OnReuse::PartialThenClose => {
                    let _ = writer.write_all(b"HTTP/1.1 200 OK\r\nContent-");
                    let _ = writer.flush();
                }
                OnReuse::HundredThenClose => {
                    let _ = writer.write_all(b"HTTP/1.1 100 Continue\r\n\r\n");
                    let _ = writer.flush();
                }
            }
            return; // drop the connection
        }

        if expect_100 {
            writer.write_all(b"HTTP/1.1 100 Continue\r\n\r\n").unwrap();
            writer.flush().unwrap();
        }

        let mut body = vec![0u8; content_length];
        reader.read_exact(&mut body).unwrap();

        requests.lock().unwrap().push(Recorded { method, target, body });

        writer
            .write_all(b"HTTP/1.1 200 OK\r\nContent-Length: 0\r\n\r\n")
            .unwrap();
        writer.flush().unwrap();
    }
}
