    /// (resolve, connect, send request, etc) applies afresh.
    pub(crate) fn for_retry(mut self) -> CallTimings {
        self.times.truncate(2); // Global and PerCall are in positions 0 and 1.

        CallTimings {
            timeouts: self.timeouts,
            per_read: self.per_read,
            per_write: self.per_write,
            current_time: self.current_time,
            times: self.times,
        }
    }

